<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import MDialog from '../../components/mds/MDialog.vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue';
import { HostSurface } from '../../platform/host-adapter.mjs'; import { ownerReassignViewModel, toOwnerReassignPayload } from '../ownership/domain/owner-reassign.mjs'; import OwnerReassignDesktop from '../ownership/desktop/OwnerReassignDesktop.vue'; import OwnerReassignMobile from '../ownership/mobile/OwnerReassignMobile.vue'; import { createEventsApi } from './domain/events-api.mjs'; import { eventDetailViewModel } from './domain/event-detail.mjs';
import EventsListDesktop from './desktop/EventsListDesktop.vue'; import EventsListMobile from './mobile/EventsListMobile.vue'; import EventCreateDesktop from './desktop/EventCreateDesktop.vue'; import EventCreateMobile from './mobile/EventCreateMobile.vue'; import EventDetailDesktop from './desktop/EventDetailDesktop.vue'; import EventDetailMobile from './mobile/EventDetailMobile.vue';
import EventCostFormDesktop from './desktop/EventCostFormDesktop.vue'; import EventCostFormMobile from './mobile/EventCostFormMobile.vue';
import EventIntakeDesktop from './desktop/EventIntakeDesktop.vue'; import EventIntakeMobile from './mobile/EventIntakeMobile.vue';
const props = defineProps({ eventId: { type: Number, default: null }, surface: String, adapter: Object, hostUnavailable: Boolean, nativeNavigation: { type: Array, default: () => [] } }); const emit = defineEmits(['back', 'navigate']); const api = createEventsApi(); const safeArea = ref(props.adapter?.getSafeArea?.() || {}); const isNative = computed(() => props.surface === HostSurface.NATIVE); const state = reactive({ phase:'loading',rows:[],total:0,page:1,pageSize:20,search:'',record:null,detail:null,permissions:null,mode:'read',saving:false,saveError:'',deleting:false,deleteError:'',ownerReassign:null,ownerId:null,ownerReassignTarget:null,ownerReassignSaving:false,ownerReassignError:'',uploading:false,fileError:'',costSaving:false,costDeleting:false,costError:'',costRecord:null,costCategory:'sponsor',suppliers:[],extracting:false,intakeError:'',intakeMissing:[],intakeWarnings:[],error:null }); const canCreate = computed(()=>state.permissions?.modules?.events?.includes('create')===true); const canEdit = computed(()=>state.permissions?.modules?.events?.includes('edit')===true); const canDelete = computed(()=>state.permissions?.modules?.events?.includes('delete')===true); const canReassignOwner=computed(()=>state.permissions?.modules?.admin?.includes('edit')===true&&Boolean(props.eventId)); const canManageCosts = computed(()=>canEdit.value && !state.detail?.costGroups?.some((group)=>group.items.some((item)=>item.amountMasked))); const safeAreaStyle = computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));
async function load({page=state.page,search=state.search}={}) { if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;} state.phase='loading'; state.error=null; try { const sessionPromise=api.getCurrentUser(); if(props.eventId){const [payload,session]=await Promise.all([api.get(props.eventId),sessionPromise]); Object.assign(state,{record:payload.record,detail:eventDetailViewModel(payload),permissions:session?.permissions||null,mode:'detail',phase:'ready'}); return;} const [p,session]=await Promise.all([api.getList({page,pageSize:state.pageSize,search}),sessionPromise]); Object.assign(state,{rows:p.rows,total:p.total,page:p.page,pageSize:p.pageSize,search,record:null,detail:null,permissions:session?.permissions||null,mode:'read',phase:'ready'}); } catch(error){state.phase='error';state.error=error;} }
function beginCreate(){if(canCreate.value){state.mode='create';state.saveError='';}} function beginIntake(){if(canCreate.value){state.intakeError='';state.intakeMissing=[];state.intakeWarnings=[];state.mode='intake';}} function beginEdit(){if(canEdit.value&&props.eventId){state.mode='edit';state.saveError='';}} async function beginOwnerReassign(){if(!canReassignOwner.value||!state.record)return;state.ownerReassignError='';state.ownerReassignTarget=null;try{state.ownerReassign=ownerReassignViewModel({record:state.record,users:await api.getAdminUsers()});state.ownerId=state.ownerReassign.ownerId;state.mode='owner-reassign';}catch(error){state.ownerReassignError=error.message;state.mode='owner-reassign';}} function requestOwnerReassign(){try{const nextOwner=toOwnerReassignPayload(state.ownerId).owner_id;if(nextOwner===state.ownerReassign?.ownerId)throw new TypeError('Hãy chọn người phụ trách khác người hiện tại.');state.ownerReassignTarget=state.ownerReassign?.owners.find((option)=>option.value===nextOwner)||null;}catch(error){state.ownerReassignError=error.message;}} async function saveOwnerReassign(){const target=state.ownerReassignTarget;if(!target)return;state.ownerReassignSaving=true;state.ownerReassignError='';try{await api.reassignOwner(props.eventId,toOwnerReassignPayload(target.value).owner_id);state.ownerReassignTarget=null;await load();}catch(error){state.ownerReassignError=error.message;state.ownerReassignTarget=null;}finally{state.ownerReassignSaving=false;}} function cancelOwnerReassign(){state.ownerReassignTarget=null;state.ownerReassignError='';state.mode='detail';} function openEvent(id){location.hash=`events/${Number(id)}`;} function showList(){location.hash='events';} async function extract(input){state.extracting=true;state.intakeError='';try{const result=await api.extract(input); const draft={...result.extracted}; if(/^\d{4}-\d{2}-\d{2}$/.test(String(draft.start_time||''))) draft.start_time=`${draft.start_time}T00:00`; state.intakeMissing=result.missing;state.intakeWarnings=result.warnings;state.record=draft;state.mode='create';}catch(error){state.intakeError=error.message;}finally{state.extracting=false;}} async function save(input){state.saving=true;try{const saved=await api.save(input, props.eventId); if(props.eventId) await load(); else location.hash=`events/${saved.id}`;}catch(error){state.saveError=error.message;}finally{state.saving=false;}} async function deleteEvent(){if(!canDelete.value||!props.eventId)return; state.deleting=true;state.deleteError='';try{await api.delete(props.eventId);showList();}catch(error){state.deleteError=error.message;}finally{state.deleting=false;}} async function uploadFiles({kind,files}){if(!canEdit.value||!props.eventId||!Array.isArray(files)||files.length===0)return; state.uploading=true;state.fileError='';try{await api.uploadFiles(props.eventId,files,{kind});await load();}catch(error){state.fileError=error.message;}finally{state.uploading=false;}} async function beginCost(payload){if(!canManageCosts.value||!props.eventId)return; const item=payload?.item||null; state.costCategory=item?.category||payload?.category||'sponsor'; state.costRecord=item; state.costError=''; state.mode='cost'; if(state.costCategory==='organization'){try{state.suppliers=await api.listSuppliers();}catch(error){state.costError=error.message;}}} async function saveCost(input){if(!canManageCosts.value||!props.eventId)return; state.costSaving=true;state.costError='';try{await api.saveCost(props.eventId,input,state.costRecord?.id);await load();}catch(error){state.costError=error.message;}finally{state.costSaving=false;}} async function deleteCost(item){if(!canDelete.value||!props.eventId||!item?.id)return; state.costDeleting=true;state.costError='';try{await api.deleteCost(props.eventId,item.id);await load();}catch(error){state.costError=error.message;}finally{state.costDeleting=false;}} async function back(){if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'events-list'});emit('back');} watch(()=>props.eventId,()=>load()); onMounted(load);
</script>
<template>
  <div v-if="state.phase === 'loading'" :class="isNative ? 'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]' : 'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28" /></div>
  <section v-else-if="state.phase === 'error'" :class="isNative ? 'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]' : 'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Sự kiện" @back="back" /><MEmptyState :title="state.error.status === 404 ? 'Không tìm thấy sự kiện' : state.error.status === 403 ? 'Bạn không có quyền xem sự kiện' : 'Không thể mở sự kiện'" :description="state.error.message" /></section>
  <OwnerReassignMobile v-else-if="isNative && state.mode === 'owner-reassign'" resource-label="Sự kiện" :title="state.detail?.title" :current-owner-label="state.ownerReassign?.currentOwnerLabel" :current-owner-id="state.ownerReassign?.ownerId" :owners="state.ownerReassign?.owners" :owner-id="state.ownerId" :saving="state.ownerReassignSaving" :error="state.ownerReassignError" :safe-area-style="safeAreaStyle" @back="cancelOwnerReassign" @update:owner-id="state.ownerId=$event" @submit="requestOwnerReassign" />
  <EventIntakeMobile v-else-if="isNative && state.mode === 'intake'" :loading="state.extracting" :error="state.intakeError" :missing="state.intakeMissing" :warnings="state.intakeWarnings" :safe-area-style="safeAreaStyle" @cancel="state.mode = 'read'" @extract="extract" />
  <EventCostFormMobile v-else-if="isNative && state.mode === 'cost'" :record="state.costRecord" :category="state.costCategory" :editing="Boolean(state.costRecord)" :saving="state.costSaving" :error="state.costError" :suppliers="state.suppliers" :safe-area-style="safeAreaStyle" @cancel="state.mode = 'detail'" @save="saveCost" />
  <EventDetailMobile v-else-if="isNative && state.mode === 'detail'" :detail="state.detail" :can-edit="canEdit" :can-delete="canDelete" :can-reassign-owner="canReassignOwner" :can-manage-costs="canManageCosts" :cost-deleting="state.costDeleting" :cost-error="state.costError" :delete-working="state.deleting" :delete-error="state.deleteError" :uploading="state.uploading" :file-error="state.fileError" :safe-area-style="safeAreaStyle" @back="showList" @edit="beginEdit" @delete="deleteEvent" @reassign-owner="beginOwnerReassign" @upload="uploadFiles" @add-cost="beginCost({ category: $event })" @edit-cost="beginCost({ item: $event })" @delete-cost="deleteCost" />
  <EventCreateMobile v-else-if="isNative && ['create', 'edit'].includes(state.mode)" :record="state.record" :editing="state.mode === 'edit'" :saving="state.saving" :error="state.saveError" :intake-missing="state.intakeMissing" :intake-warnings="state.intakeWarnings" :safe-area-style="safeAreaStyle" @cancel="state.mode = props.eventId ? 'detail' : 'read'" @save="save" />
  <EventsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :can-create="canCreate" :can-intake="canCreate" :safe-area-style="safeAreaStyle" :native-navigation="nativeNavigation" @back="back" @create="beginCreate" @intake="beginIntake" @open="openEvent" @navigate="emit('navigate', $event)" @search="load({ page: 1, search: $event })" @page="load({ page: $event })" />
  <OwnerReassignDesktop v-else-if="state.mode === 'owner-reassign'" resource-label="Sự kiện" :title="state.detail?.title" :current-owner-label="state.ownerReassign?.currentOwnerLabel" :current-owner-id="state.ownerReassign?.ownerId" :owners="state.ownerReassign?.owners" :owner-id="state.ownerId" :saving="state.ownerReassignSaving" :error="state.ownerReassignError" @back="cancelOwnerReassign" @update:owner-id="state.ownerId=$event" @submit="requestOwnerReassign" />
  <EventIntakeDesktop v-else-if="state.mode === 'intake'" :loading="state.extracting" :error="state.intakeError" :missing="state.intakeMissing" :warnings="state.intakeWarnings" @cancel="state.mode = 'read'" @extract="extract" />
  <EventCostFormDesktop v-else-if="state.mode === 'cost'" :record="state.costRecord" :category="state.costCategory" :editing="Boolean(state.costRecord)" :saving="state.costSaving" :error="state.costError" :suppliers="state.suppliers" @cancel="state.mode = 'detail'" @save="saveCost" />
  <EventDetailDesktop v-else-if="state.mode === 'detail'" :detail="state.detail" :can-edit="canEdit" :can-delete="canDelete" :can-reassign-owner="canReassignOwner" :can-manage-costs="canManageCosts" :cost-deleting="state.costDeleting" :cost-error="state.costError" :delete-working="state.deleting" :delete-error="state.deleteError" :uploading="state.uploading" :file-error="state.fileError" @back="showList" @edit="beginEdit" @delete="deleteEvent" @reassign-owner="beginOwnerReassign" @upload="uploadFiles" @add-cost="beginCost({ category: $event })" @edit-cost="beginCost({ item: $event })" @delete-cost="deleteCost" />
  <EventCreateDesktop v-else-if="['create', 'edit'].includes(state.mode)" :record="state.record" :editing="state.mode === 'edit'" :saving="state.saving" :error="state.saveError" :intake-missing="state.intakeMissing" :intake-warnings="state.intakeWarnings" @cancel="state.mode = props.eventId ? 'detail' : 'read'" @save="save" />
  <EventsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :can-create="canCreate" :can-intake="canCreate" @create="beginCreate" @intake="beginIntake" @open="openEvent" @search="load({ page: 1, search: $event })" @page="load({ page: $event })" />
  <MDialog :model-value="Boolean(state.ownerReassignTarget)" title="Xác nhận gán lại người phụ trách?" type="danger" confirm-text="Gán lại" @update:model-value="!$event&&(state.ownerReassignTarget=null)" @confirm="saveOwnerReassign"><p>Sự kiện sẽ được gán cho <strong>{{ state.ownerReassignTarget?.label }}</strong>. Máy chủ sẽ kiểm tra lại quyền Admin và trạng thái tài khoản trước khi lưu.</p></MDialog>
</template>
